#!/usr/bin/env bash
set -euo pipefail

# Agricore: migrate the payment adapter from Flutterwave to IntaSend.
# - adds  utils/payments.py        (IntaSend adapter: payouts, bank list, checkout)
# - turns utils/flutterwave.py     into a compatibility shim re-exporting it
# - adds  INTASEND_* to settings.py (read from .env, like the SMS vars)
# Safe, idempotent, dev-branch only, backs up + restores on any failure.

PAY="utils/payments.py"
FW="utils/flutterwave.py"

BR="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo '')"
if [ -n "$BR" ] && [ "$BR" != "dev" ]; then
  echo ">> Refusing: current branch is '$BR', not 'dev'."; exit 1
fi
[ -f "$FW" ] || { echo ">> Not found: $FW  (run from the Django root, where manage.py lives)"; exit 1; }

SETTINGS="$(grep -rl 'INSTALLED_APPS' --include=settings.py . 2>/dev/null | grep -v '_backup_' | head -1 || true)"
[ -n "$SETTINGS" ] || SETTINGS="agricore_project/settings.py"
[ -f "$SETTINGS" ] || { echo ">> Not found: settings.py (looked for INSTALLED_APPS)"; exit 1; }
echo ">> settings.py: $SETTINGS"

TS="$(date +%Y%m%d-%H%M%S)"
BK="intasend_backup_${TS}"
mkdir -p "$BK/utils"
cp -a "$FW" "$BK/utils/flutterwave.py"
[ -f "$PAY" ] && cp -a "$PAY" "$BK/utils/payments.py" || true
cp -a "$SETTINGS" "$BK/settings.py"
[ -f .env ] && cp -a .env "$BK/.env" || true
echo ">> Backup: $BK/"

set +e
python3 - "$PAY" "$FW" "$SETTINGS" <<'PYEOF'
import sys, ast, base64
PAY, FW, SETTINGS = sys.argv[1], sys.argv[2], sys.argv[3]
payments = base64.b64decode("").decode("utf-8")
shim     = base64.b64decode("").decode("utf-8")
setblk   = base64.b64decode("").decode("utf-8")

# 1) utils/payments.py  (canonical IntaSend adapter)
import os
if os.path.exists(PAY) and "Payment provider adapter for Agricore" in open(PAY, encoding="utf-8").read():
    print("   utils/payments.py already present, skip")
else:
    ast.parse(payments)
    open(PAY, "w", encoding="utf-8").write(payments)
    print("   OK utils/payments.py written")

# 2) utils/flutterwave.py -> shim  (idempotent)
cur = open(FW, encoding="utf-8").read()
if "from utils.payments import" in cur:
    print("   flutterwave.py already a shim, skip")
else:
    ast.parse(shim)
    open(FW, "w", encoding="utf-8").write(shim)
    print("   OK utils/flutterwave.py is now a shim over utils/payments")

# 3) settings.py append  (idempotent)
s = open(SETTINGS, encoding="utf-8").read()
if "Agricore IntaSend env (idempotent)" in s:
    print("   settings.py IntaSend block present, skip")
else:
    new = s.rstrip("\n") + "\n\n\n" + setblk.rstrip("\n") + "\n"
    ast.parse(new)
    open(SETTINGS, "w", encoding="utf-8").write(new)
    print("   OK settings.py: INTASEND_* added (read from .env)")
PYEOF
rc=$?
set -e

if [ "$rc" -ne 0 ]; then
  echo ">> Patch failed (rc=$rc). Restoring backup."
  cp -a "$BK/utils/flutterwave.py" "$FW"
  if [ -f "$BK/utils/payments.py" ]; then cp -a "$BK/utils/payments.py" "$PAY"; else rm -f "$PAY"; fi
  cp -a "$BK/settings.py" "$SETTINGS"
  exit "$rc"
fi

# 4) .env placeholders (idempotent; only if .env exists)
if [ -f .env ]; then
  if grep -q "INTASEND_SECRET_KEY" .env; then
    echo "   .env already has IntaSend keys, skip"
  else
    cat >> .env <<'ENVEOF'

# --- IntaSend (paste real keys from the IntaSend dashboard; sandbox keys for now) ---
INTASEND_TEST=True
INTASEND_PUBLISHABLE_KEY=ISPubKey_test_PASTE_HERE
INTASEND_SECRET_KEY=ISSecretKey_test_PASTE_HERE
ENVEOF
    echo "   OK .env: IntaSend placeholders appended"
  fi
else
  echo "   NOTE: no .env found here; add INTASEND_TEST / INTASEND_PUBLISHABLE_KEY / INTASEND_SECRET_KEY to your environment."
fi

echo
echo "DONE"
echo ">> Restart the server. No migration needed."
echo ">> Rollback: cp -a $BK/utils/flutterwave.py $FW ; cp -a $BK/settings.py $SETTINGS ; (and your .env)"
